// Normalize two public API responses. Work only with supplied data; no secrets.
const incoming = $input.all().map(item => item.json);
const rows = [];
for (const payload of incoming) {
  if (Array.isArray(payload.items)) {
    for (const r of payload.items) {
      rows.push({kind:'github',title:r.full_name || r.name,url:r.html_url,
        description:(r.description || '').slice(0,280),
        stars:r.stargazers_count || 0,updated_at:r.updated_at || null});
    }
  }
  if (Array.isArray(payload.hits)) {
    for (const r of payload.hits) {
      const url = r.url || (r.objectID ? 'https://news.ycombinator.com/item?id=' + r.objectID : '');
      rows.push({kind:'hn',title:r.title || r.story_title || '',url,
        description:'Hacker News discussion / public story',
        points:r.points || 0,updated_at:r.created_at || null});
    }
  }
}
const seen = new Set();
const selected = rows.filter(r => {
  if (!r.title || !/^https:\/\//.test(r.url || '') || seen.has(r.url)) return false;
  seen.add(r.url); return true;
}).filter(r=>/(ai|agent|automation|marketing|workflow|llm|mcp|codex|github|n8n)/i.test(r.title+' '+r.description))
.sort((a,b)=>(b.kind==='github'?b.stars:b.points || 0)-(a.kind==='github'?a.stars:a.points || 0))
.slice(0,18);
if (!selected.length) return [{json:{prompt:'沒有取得可靠候選來源。請回報資料收集失敗，不要編造。',sources:[]}}];
return [{json:{
  checked_at:new Date().toISOString(),
  sources:selected,
  prompt:'請根據以下真實來源元資料（不是全文）提出 Javia AI Lab 的研究選題與實驗：\n'+JSON.stringify(selected,null,2)
}}];
